async function fetchData(...args){const response=await fetch(...args);if(!response.ok){throw new Error(`HTTP status code: ${response.status}`,{cause:response})}return response}export class FetchUtil{constructor({baseUrl,clientId}){this.baseUrl=baseUrl,this.clientId=clientId}async get({headers,signal,cache,...args}){const url=this.createUrl(args);return(await fetchData(url,{method:"GET",headers,signal,cache})).json()}async getBlob({headers,signal,...args}){const url=this.createUrl(args);return(await fetchData(url,{method:"GET",headers,signal})).blob()}async post({body,headers,signal,...args}){const url=this.createUrl(args);return(await fetchData(url,{method:"POST",headers,body:body?JSON.stringify(body):void 0,signal})).json()}async put({body,headers,signal,...args}){const url=this.createUrl(args);return(await fetchData(url,{method:"PUT",headers,body:body?JSON.stringify(body):void 0,signal})).json()}async delete({body,headers,signal,...args}){const url=this.createUrl(args);return(await fetchData(url,{method:"DELETE",headers,body:body?JSON.stringify(body):void 0,signal})).json()}createUrl({path,params}){const url=new URL(path,this.baseUrl);return params&&Object.entries(params).forEach(([key,value])=>{value&&url.searchParams.append(key,value)}),this.clientId&&url.searchParams.append("clientId",this.clientId),url}}